TUTORIALS.append({'title': 'CP-4. queries.py', 'category': 'programming', 'order': 4, 'summary': 'All the SQL: client name, accounts, ACTIVE deals, account↔deal links, 6-month turnover, overdue history (dealfact). Change the get_oracle_connection import line to your path.', 'content': '<p>Step 4 of 9. Save as <code>cprofile/queries.py</code>.</p>\n<h3>queries.py</h3>\n<pre><code class="language-python">"""\nAll SQL of the client portfolio, and nothing else.\n\nSix small queries instead of one big join. Each one returns rows that cannot repeat,\nand Python (logic.py) puts them together. Why not one join: the client\'s current\naccount (20208) is linked in dealid_connection to EVERY deal it ever served, so a join\nmultiplied the rows (15 accounts became 210).\n\nParameters everywhere: :pdate (date) and :contragentid (number).\nTo run a query by hand in your SQL tool, replace :pdate / :contragentid with &amp;pdate / &amp;contragentid.\nAmounts in the database are in tiyin, so everything is divided by 100.\n"""\n# ⚠️ Change this one line to wherever your get_oracle_connection() lives.\nfrom main.oracle import get_oracle_connection\n\n\n# Q0. Client name.\nSQL_CLIENT = """\nselect c.name as contragent_name\nfrom   schema_1.contragent_table c\nwhere  c.id      = :contragentid\nand    c.arcdate = :pdate\n"""\n\n# Q1. ACCOUNTS: every account of the client with a non-zero balance on the date.\n#     Loans (asset accounts) come out NEGATIVE, deposits positive.\nSQL_ACCOUNTS = """\nselect t.id                       as account_id,\n       t.accountno,\n       substr(t.accountno, 1, 5)  as bal_acc,         -- 12501, 20208 ...\n       substr(t.accountno, 6, 3)  as currency_code,   -- 000 so\'m, 840 USD ...\n       t.toboid,\n       t.summanoweq / 100         as saldo\nfrom   schema_1.account_table_1 t\nwhere  t.arcdate      = :pdate\nand    t.contragentid = :contragentid\nand    t.summanoweq  &lt;&gt; 0\norder by t.accountno\n"""\n\n# ACTIVE DEALS: a deal is active if one of its asset accounts (1xxxx: loan, overdue,\n# interest) has money on it on the date. The current account 20208 is linked to every\n# deal the client ever had, so it is deliberately NOT used here: with it, every old\n# closed deal came back. Used inside Q2 and Q3 below.\nACTIVE_DEALS = """\nwith active as (\n    select distinct dl.dealid\n    from   schema_2.dealid_connection dl\n    join   schema_1.account_table_1 t on t.id = dl.accountid\n    where  t.arcdate      = :pdate\n    and    t.contragentid = :contragentid\n    and    t.summanoweq  &lt;&gt; 0\n    and    substr(t.accountno, 1, 1) = \'1\'\n    and    dl.daiusettingid &lt;&gt; 0\n)\n"""\n\n# Q2. DEALS: the client\'s ACTIVE deals on the date, from portfel.\n#     currency_rate.base is always 1, so given_amount_eq = givenamount * rate / 100.\nSQL_DEALS = ACTIVE_DEALS + """\nselect p.dealid,\n       p.facilitydealid                     as rnk_dealid,\n       p.expectedclosedate                  as close_date,\n       p.currencyid,\n       p.givenamount / 100                  as given_amount,\n       p.givenamount * nvl(r.rate, 1) / 100 as given_amount_eq\nfrom   schema_2.portfel_table p\nleft join schema_2.currency_rate r\n       on r.arcdate    = p.arcdate\n      and r.currencyid = p.currencyid\nwhere  p.arcdate      = :pdate\nand    p.contragentid = :contragentid\nand    p.dealid in (select dealid from active)\norder by p.dealid\n"""\n\n# Q3. LINKS: which account belongs to which ACTIVE deal.\nSQL_LINKS = ACTIVE_DEALS + """\nselect distinct dl.accountid, dl.dealid\nfrom   schema_2.dealid_connection dl\nwhere  dl.daiusettingid &lt;&gt; 0\nand    dl.dealid in (select dealid from active)\n"""\n\n# Q4. TURNOVER: money in / out of the client\'s current and card accounts,\n#     month by month, for the 6 full months before the month of :pdate.\n#     Positions 10-17 of an account number = client code; if both sides have the same\n#     code it is the client moving his own money (own transfer, loan issued to himself,\n#     loan repayment), so it is left out.\nSQL_TURNOVER = """\nwith my_acc as (\n    select accountno\n    from   schema_1.account_table_1\n    where  arcdate      = :pdate\n    and    contragentid = :contragentid\n    and   (substr(accountno, 1, 3) = \'202\'                                  -- demand deposits\n           or substr(accountno, 1, 5) in (\'22618\', \'22619\', \'22620\', \'22621\')) -- card accounts\n)\nselect \'IN\'                    as direction,\n       trunc(d.arcdate, \'MM\')  as month,\n       sum(d.summaeq) / 100    as amount,\n       count(*)                as docs\nfrom   schema_1.account d\njoin   my_acc m on m.accountno = d.accountbno\nwhere  d.arcdate &gt;= add_months(trunc(:pdate, \'MM\'), -6)\nand    d.arcdate &lt;  trunc(:pdate, \'MM\')\nand    substr(d.accountano, 10, 8) &lt;&gt; substr(d.accountbno, 10, 8)\ngroup by trunc(d.arcdate, \'MM\')\nunion all\nselect \'OUT\',\n       trunc(d.arcdate, \'MM\'),\n       sum(d.summaeq) / 100,\n       count(*)\nfrom   schema_1.account d\njoin   my_acc m on m.accountno = d.accountano\nwhere  d.arcdate &gt;= add_months(trunc(:pdate, \'MM\'), -6)\nand    d.arcdate &lt;  trunc(:pdate, \'MM\')\nand    substr(d.accountano, 10, 8) &lt;&gt; substr(d.accountbno, 10, 8)\ngroup by trunc(d.arcdate, \'MM\')\n"""\n\n\n# Q5. OVERDUE HISTORY: every overdue episode that touches the last 6 months, over ALL the\n#     client\'s deals in portfel (closed ones too: a loan repaid last month with 60 days\n#     overdue still matters). dealfacttypeid 1 = principal, 2 = interest.\n#     valuedate = overdue started, tilldate = overdue ended (01.01.3500 = still open).\n#     Old start is fine as long as it ended inside the window or is still open.\nSQL_OVERDUE = """\nselect f.dealid, f.dealfacttypeid, f.valuedate, f.tilldate\nfrom   schema_2.dealfact f\nwhere  f.dealid in (select p.dealid\n                    from   schema_2.portfel_table p\n                    where  p.arcdate      = :pdate\n                    and    p.contragentid = :contragentid)\nand    f.dealfacttypeid in (1, 2)\nand    f.valuedate &lt;= :pdate\nand    f.tilldate  &gt;= add_months(trunc(:pdate, \'MM\'), -6)\n"""\n\n\ndef fetch(cur, sql, params):\n    """Run one query and return a list of dicts with lower-case keys."""\n    cur.execute(sql, params)\n    cols = [c[0].lower() for c in cur.description]\n    return [dict(zip(cols, row)) for row in cur.fetchall()]\n\n\ndef load_client(contragentid, pdate):\n    """Everything the portfolio page needs, straight from Oracle, no calculations."""\n    params = {"pdate": pdate, "contragentid": contragentid}\n    with get_oracle_connection() as conn:\n        cur = conn.cursor()\n        client = fetch(cur, SQL_CLIENT, params)\n        return {\n            "name": client[0]["contragent_name"] if client else None,\n            "accounts": fetch(cur, SQL_ACCOUNTS, params),\n            "deals": fetch(cur, SQL_DEALS, params),\n            "links": fetch(cur, SQL_LINKS, params),\n            "turnover": fetch(cur, SQL_TURNOVER, params),\n            "overdue": fetch(cur, SQL_OVERDUE, params),\n        }\n</code></pre>\n'})

TUTORIALS.append({'title': 'CP-5. accounts.py', 'category': 'programming', 'order': 5, 'summary': 'The CBU chart of accounts as Python dicts: first 5 digits → loan / interest / deposit / off-balance, with status and a Russian label.', 'content': '<p>Step 5 of 9. Save as <code>cprofile/accounts.py</code>.</p>\n<h3>accounts.py</h3>\n<pre><code class="language-python">"""\nWhat an account is, from the first 5 digits of its number.\n\nSource: the CBU chart of accounts for commercial banks, lex.uz/ru/docs/-5744540.\nAccount number = CCCCC VVV K SSSSSSSS NNN\n                 balance  currency  check  client code  serial\n                 account  (3)       digit  (8)          (3)\n\nclassify(\'13105\') -&gt; {\'section\': \'loan\', \'status\': \'overdue\', \'label\': \'Краткосрочный · Юрлица\', ...}\n\nSections: loan · interest · deposit · offbalance · other.\nChange a name or add an account here: nothing else needs to know.\n"""\n\n# ── Loans: main account (first 3 digits) → (term, borrower) ─────────────────────────\nSHORT = {\n    \'121\': \'Банки\', \'123\': \'Правительство\', \'124\': \'Бюджетные организации\',\n    \'125\': \'Физлица\', \'126\': \'ИП\', \'127\': \'Госпредприятия\', \'128\': \'Фонд развития МСБ\',\n    \'129\': \'Предприятия с иностр. инвест.\', \'130\': \'ННО\', \'131\': \'Юрлица\', \'132\': \'НБФИ\', \'133\': \'Сельхозпроизводители\',\n}\nLONG = {\n    \'143\': \'Сельхозпроизводители\', \'144\': \'Фонд развития МСБ\', \'145\': \'Банки\', \'147\': \'Правительство\',\n    \'148\': \'Бюджетные организации\', \'149\': \'Физлица\', \'150\': \'ИП\', \'151\': \'Госпредприятия\',\n    \'152\': \'ННО\', \'153\': \'Предприятия с иностр. инвест.\', \'154\': \'НБФИ\', \'155\': \'Юрлица\',\n}\nLEASING_BORROWER = {   # 156xx: the last two digits say who the lessee is\n    \'01\': \'Банки\', \'05\': \'ИП\', \'07\': \'Госпредприятия\', \'09\': \'Предприятия с иностр. инвест.\',\n    \'11\': \'ННО\', \'13\': \'Юрлица\', \'15\': \'НБФИ\',\n    \'17\': \'просрочка\', \'19\': \'реструктуризация\', \'99\': \'резерв\',\n}\nCOURT_BORROWER = {\'01\': \'Юрлица\', \'03\': \'Физлица\', \'05\': \'Лизинг\', \'07\': \'ИП\'}  # 157xx\n\n# A few sub-accounts worth naming on their own.\nLOAN_PRODUCT = {\n    \'12503\': \'карта\', \'14913\': \'карта\',\n    \'12504\': \'ипотека (госпрограмма)\', \'14903\': \'ипотека (госпрограмма)\',\n    \'12531\': \'самозанятые\', \'14931\': \'самозанятые\',\n}\n\n# ── Accrued interest receivable (163xx) ──────────────────────────────────────────────\nINTEREST = {\n    \'16309\': (\'current\', \'Начисленные проценты по кредитам\'),\n    \'16323\': (\'current\', \'Начисленные проценты по лизингу\'),\n    \'16377\': (\'overdue\', \'Просроченные проценты\'),\n    \'16379\': (\'restructured\', \'Проценты с продлённым сроком\'),\n    \'16398\': (\'reserve\', \'Резерв по прочим активам\'),\n    \'16399\': (\'reserve\', \'Резерв по процентам\'),\n}\n\n# ── Deposits ─────────────────────────────────────────────────────────────────────────\nDEPOSIT_KIND = {\'202\': \'До востребования\', \'204\': \'Сберегательный\', \'206\': \'Срочный\'}\nDEPOSITOR = {   # last two digits of 202xx / 204xx / 206xx\n    \'02\': \'гос. внебюджетные фонды\', \'03\': \'бюджетные организации\', \'04\': \'бюджетные организации\',\n    \'05\': \'внебюджетные фонды\', \'06\': \'физлица\', \'08\': \'частные предприятия\',\n    \'10\': \'госпредприятия\', \'12\': \'ННО\', \'14\': \'предприятия с иностр. инвест.\',\n    \'16\': \'НБФИ\', \'18\': \'ИП\', \'96\': \'прочие\',\n}\nDEPOSIT_OTHER = {\n    \'22602\': \'Покрытие по аккредитиву\', \'22606\': \'Покрытие по импортным векселям\',\n    \'22613\': \'Средства на конвертацию\', \'22614\': \'Сконвертированные средства\',\n    \'22616\': \'Средства ДБО физлиц\', \'22617\': \'Карта пенсионера\', \'22618\': \'Карта физлица\',\n    \'22619\': \'Карта ИП\', \'22620\': \'Корпоративная карта\', \'22621\': \'Карта самозанятого\',\n    \'22650\': \'Депонент\',\n}\n\n# ── Off-balance (9xxxx) → (kind, name) ───────────────────────────────────────────────\nOFFBALANCE = {\n    \'91809\': (\'unused\', \'Неиспользованные кредитные линии\'),\n    \'91901\': (\'commitment\', \'Обязательства заёмщика: краткосрочные\'),\n    \'91905\': (\'commitment\', \'Обязательства заёмщика: долгосрочные\'),\n    \'91907\': (\'commitment\', \'Обязательства заёмщика: госкредиты\'),\n    \'94501\': (\'collateral\', \'Залог: ценные бумаги\'),\n    \'94502\': (\'collateral\', \'Залог: имущество и права\'),\n    \'94503\': (\'collateral\', \'Залог: гарантии и поручительства\'),\n    \'94511\': (\'collateral\', \'Залог по прочим активам: ценные бумаги\'),\n    \'94512\': (\'collateral\', \'Залог по прочим активам: имущество\'),\n    \'94513\': (\'collateral\', \'Залог по прочим активам: гарантии\'),\n    \'90993\': (\'guarantee\', \'Выданные гарантии и поручительства\'),\n    \'91501\': (\'interest_off\', \'Проценты вне баланса\'),\n    \'91503\': (\'interest_off\', \'Проценты с продлённым сроком (вне баланса)\'),\n    \'91505\': (\'interest_off\', \'Проценты и комиссии вне баланса\'),\n    \'95409\': (\'claim\', \'Требования, предъявленные должнику\'),\n    \'95413\': (\'written_off\', \'Списанные кредиты, лизинг, факторинг\'),\n    \'95415\': (\'written_off\', \'Прочие списанные активы\'),\n}\n\nSTATUS_NAMES = {\n    \'current\': \'Срочные\', \'restructured\': \'Реструкт.\', \'overdue\': \'Просрочка\',\n    \'court\': \'Суд\', \'reserve\': \'Резерв\',\n}\n\n\ndef _loan(code):\n    main, sub = code[:3], code[3:]\n    if main in SHORT:\n        status = {\'05\': \'overdue\', \'09\': \'restructured\', \'99\': \'reserve\'}.get(sub, \'current\')\n        # 05 holds overdue loans of BOTH terms (13105 takes 15501/15505 too), so it is not\n        # labelled «Краткосрочный»: it gets its own row\n        label = (\'Просрочка · \' if sub == \'05\' else \'Краткосрочный · \') + SHORT[main]\n    elif main in LONG:\n        # long-term has no overdue sub-account: 05 is RESTRUCTURED here\n        status = {\'05\': \'restructured\', \'99\': \'reserve\'}.get(sub, \'current\')\n        label = \'Долгосрочный · \' + LONG[main]\n    elif main == \'156\':\n        status = {\'17\': \'overdue\', \'19\': \'restructured\', \'99\': \'reserve\'}.get(sub, \'current\')\n        label = \'Лизинг · \' + LEASING_BORROWER.get(sub, \'прочие\')\n    elif main == \'157\':\n        status = \'reserve\' if sub == \'99\' else \'court\'\n        label = \'Суд / принудительное взыскание · \' + COURT_BORROWER.get(sub, \'прочие\')\n    elif main == \'111\':\n        status = {\'03\': \'overdue\', \'05\': \'court\', \'99\': \'reserve\'}.get(sub, \'current\')\n        label = \'Факторинг\'\n    elif \'121\' &lt;= main &lt;= \'155\':\n        # safety net: a loan account this map does not know yet still counts as a loan\n        status = \'reserve\' if sub == \'99\' else \'current\'\n        label = f\'Кредиты · счёт {main}00 (добавьте в accounts.py)\'\n    else:\n        return None\n    if code in LOAN_PRODUCT:\n        label += \' (\' + LOAN_PRODUCT[code] + \')\'\n    return {\'section\': \'loan\', \'status\': status, \'label\': label}\n\n\ndef classify(code):\n    """5-digit balance account -&gt; dict with section, status/kind and a Russian label."""\n    code = (code or \'\')[:5]\n\n    loan = _loan(code)\n    if loan:\n        return loan\n\n    if code.startswith(\'163\'):\n        status, label = INTEREST.get(code, (\'current\', \'Прочие начисленные проценты\'))\n        return {\'section\': \'interest\', \'status\': status, \'label\': label}\n\n    if code[:3] in DEPOSIT_KIND:\n        who = DEPOSITOR.get(code[3:], \'прочие\')\n        return {\'section\': \'deposit\', \'kind\': code[:3], \'label\': f\'{DEPOSIT_KIND[code[:3]]} · {who}\'}\n    if code in DEPOSIT_OTHER:\n        return {\'section\': \'deposit\', \'kind\': \'226\', \'label\': DEPOSIT_OTHER[code]}\n    if code.startswith(\'224\'):\n        return {\'section\': \'deposit\', \'kind\': \'224\', \'label\': \'Начисленные проценты к выплате\'}\n\n    if code in OFFBALANCE:\n        kind, label = OFFBALANCE[code]\n        return {\'section\': \'offbalance\', \'kind\': kind, \'label\': label}\n    if code.startswith(\'909\'):\n        return {\'section\': \'offbalance\', \'kind\': \'trade\', \'label\': \'Аккредитивы и инкассо\'}\n    if code.startswith(\'9\'):\n        return {\'section\': \'offbalance\', \'kind\': \'other\', \'label\': \'Прочие внебалансовые\'}\n\n    return {\'section\': \'other\', \'label\': \'Прочие счета\'}\n\n\ndef client_type(codes):\n    """Guess the client type from the accounts he has: company, IP or person."""\n    codes = set(codes)\n    if codes &amp; {\'20208\', \'20210\', \'20212\', \'20214\', \'20216\', \'22620\'} or any(\n            c[:3] in (\'127\', \'129\', \'131\', \'151\', \'153\', \'155\') for c in codes):\n        return \'Юридическое лицо\'\n    if codes &amp; {\'20218\', \'22619\'} or any(c[:3] in (\'126\', \'150\') for c in codes):\n        return \'Индивидуальный предприниматель\'\n    if codes &amp; {\'20206\', \'20406\', \'20606\', \'22617\', \'22618\'} or any(\n            c[:3] in (\'125\', \'149\') for c in codes):\n        return \'Физическое лицо\'\n    return \'—\'\n</code></pre>\n'})

TUTORIALS.append({'title': 'CP-6. logic.py', 'category': 'programming', 'order': 6, 'summary': 'All the calculations: loans by product, active deals, credit lines (RNK), deposits, off-balance, turnover, overdue days per month, KPIs.', 'content': '<p>Step 6 of 9. Save as <code>cprofile/logic.py</code>.</p>\n<h3>logic.py</h3>\n<pre><code class="language-python">"""\nThe portfolio: takes the raw rows from queries.load_client() and builds what the page shows.\n\nNo SQL here and no HTML: plain Python lists and dicts, so every number can be checked by hand.\n\nSign: in the database loans are negative and deposits positive. Here every amount is shown\nas a positive number (abs), and the section says what it is.\n"""\nfrom collections import defaultdict\nfrom datetime import date, datetime, timedelta\n\nfrom .accounts import STATUS_NAMES, classify, client_type\n\nMONTHS_RU = [\'Январь\', \'Февраль\', \'Март\', \'Апрель\', \'Май\', \'Июнь\', \'Июль\', \'Август\',\n             \'Сентябрь\', \'Октябрь\', \'Ноябрь\', \'Декабрь\']\nTURNOVER_MONTHS = 6\nSOON_DAYS = 30          # a deal closing within this many days gets a yellow badge\n\n\ndef _day(v):\n    """Oracle gives datetime; we compare dates."""\n    return v.date() if isinstance(v, datetime) else v\n\n\ndef _pct(part, whole):\n    return round(100 * part / whole, 1) if whole else None\n\n\ndef _pct_txt(part, whole):\n    """\'1,2%\' the Russian way, for the KPI notes."""\n    return f\'{_pct(part, whole) or 0}%\'.replace(\'.\', \',\')\n\n\ndef _month_end(first):\n    """date(2026, 2, 1) -&gt; date(2026, 2, 28)"""\n    nxt = date(first.year + first.month // 12, first.month % 12 + 1, 1)\n    return nxt - timedelta(days=1)\n\n\ndef _month_starts(pdate, n):\n    """The n full months before pdate\'s month, oldest first: [date(2026,4,1), ..., date(2026,9,1)]."""\n    y, m = pdate.year, pdate.month\n    out = []\n    for _ in range(n):\n        m -= 1\n        if m == 0:\n            y, m = y - 1, 12\n        out.append(date(y, m, 1))\n    return out[::-1]\n\n\ndef _loans_table(loans):\n    """One row per product (term · borrower): columns by status, plus the gross total."""\n    rows = defaultdict(lambda: {k: 0.0 for k in STATUS_NAMES})\n    for a in loans:\n        rows[a[\'label\']][a[\'status\']] += a[\'amount\']\n    out = []\n    for label, r in sorted(rows.items()):\n        gross = r[\'current\'] + r[\'restructured\'] + r[\'overdue\'] + r[\'court\']\n        out.append({\'label\': label, **r, \'gross\': gross, \'net\': gross - r[\'reserve\']})\n    return out\n\n\ndef _sum_by_label(accs):\n    rows = defaultdict(lambda: {\'amount\': 0.0, \'count\': 0})\n    for a in accs:\n        rows[a[\'label\']][\'amount\'] += a[\'amount\']\n        rows[a[\'label\']][\'count\'] += 1\n    total = sum(r[\'amount\'] for r in rows.values())\n    return [{\'label\': k, **v, \'share\': _pct(v[\'amount\'], total)}\n            for k, v in sorted(rows.items(), key=lambda kv: -kv[1][\'amount\'])], total\n\n\ndef _overdue(facts, pdate, months):\n    """Overdue days from dealfact.\n\n    Per month: for every overdue episode that touches the month, days = (episode end, or the\n    last day of the month if it was still open then) − start + 1 (the first day counts).\n    The month gets the MAX,\n    separately for principal (type 1) and interest (type 2).\n    Per deal: days overdue ON pdate (episodes still open that day).\n    """\n    per_month = []\n    for start in months:\n        end = _month_end(start)\n        worst = {1: 0, 2: 0}\n        for f in facts:\n            began, ended = _day(f[\'valuedate\']), _day(f[\'tilldate\'])\n            if began &gt; end or ended &lt; start:\n                continue                                  # episode not in this month\n            days = (min(ended, end) - began).days + 1\n            worst[f[\'dealfacttypeid\']] = max(worst[f[\'dealfacttypeid\']], days)\n        per_month.append(worst)\n\n    now = defaultdict(int)\n    for f in facts:\n        began, ended = _day(f[\'valuedate\']), _day(f[\'tilldate\'])\n        if began &lt;= pdate &lt; ended:\n            now[f[\'dealid\']] = max(now[f[\'dealid\']], (pdate - began).days + 1)\n    return per_month, now\n\n\ndef _deals(deals, links, by_id, pdate, overdue_now):\n    """Each ACTIVE deal (balance &gt; 0) with the balances of its own accounts."""\n    accounts_of = defaultdict(set)\n    for l in links:\n        accounts_of[l[\'dealid\']].add(l[\'accountid\'])\n\n    out = []\n    for d in deals:\n        accs = [by_id[i] for i in accounts_of[d[\'dealid\']] if i in by_id]\n        loan = [a for a in accs if a[\'section\'] == \'loan\' and a[\'status\'] != \'reserve\']\n        balance = sum(a[\'amount\'] for a in loan)\n        overdue = sum(a[\'amount\'] for a in loan if a[\'status\'] in (\'overdue\', \'court\'))\n        interest = sum(a[\'amount\'] for a in accs\n                       if a[\'section\'] == \'interest\' and a[\'status\'] != \'reserve\')\n        unused = sum(a[\'amount\'] for a in accs\n                     if a[\'section\'] == \'offbalance\' and a[\'kind\'] == \'unused\')\n        if balance &lt;= 0:\n            continue                                      # nothing left on it: not shown\n        given = d[\'given_amount_eq\'] or 0\n        overdue_days = overdue_now.get(d[\'dealid\'], 0)\n        close = _day(d[\'close_date\'])\n        days_left = (close - pdate).days if close else None\n\n        if overdue or overdue_days:\n            flag = (\'danger\', \'Просрочка\')\n        elif days_left is not None and days_left &lt; 0 and balance:\n            flag = (\'danger\', \'Срок истёк\')\n        elif days_left is not None and days_left &lt;= SOON_DAYS:\n            flag = (\'warning\', \'Скоро закрытие\')\n        else:\n            flag = None\n\n        out.append({\n            \'dealid\': d[\'dealid\'], \'rnk_dealid\': d[\'rnk_dealid\'], \'currencyid\': d[\'currencyid\'],\n            \'given\': given, \'given_fx\': d[\'given_amount\'], \'balance\': balance,\n            \'overdue\': overdue, \'overdue_days\': overdue_days, \'interest\': interest, \'unused\': unused,\n            \'close_date\': close, \'days_left\': days_left, \'flag\': flag,\n            \'loan_accounts\': sorted(a[\'accountno\'] for a in loan),\n            \'account_ids\': {a[\'account_id\'] for a in loan},\n        })\n    out.sort(key=lambda x: -x[\'balance\'])\n    return out\n\n\ndef _rnk(deals):\n    """Deals with the same facilitydealid = one credit line (RNK). No limit: just what was given."""\n    groups = defaultdict(list)\n    for d in deals:\n        if d[\'rnk_dealid\']:\n            groups[d[\'rnk_dealid\']].append(d)\n    out = []\n    for rnk, ds in groups.items():\n        closes = [d[\'close_date\'] for d in ds if d[\'close_date\']]\n        out.append({\n            \'rnk_dealid\': rnk, \'deals\': len(ds),\n            \'given\': sum(d[\'given\'] for d in ds), \'balance\': sum(d[\'balance\'] for d in ds),\n            \'overdue\': sum(d[\'overdue\'] for d in ds), \'unused\': sum(d[\'unused\'] for d in ds),\n            \'last_close\': max(closes) if closes else None,\n            \'days_left\': max(d[\'days_left\'] for d in ds if d[\'days_left\'] is not None)\n            if closes else None,\n        })\n    out.sort(key=lambda x: -x[\'balance\'])\n    return out\n\n\ndef _turnover(rows, pdate):\n    months = _month_starts(pdate, TURNOVER_MONTHS)\n    data = {m: {\'in\': 0.0, \'out\': 0.0, \'in_docs\': 0, \'out_docs\': 0} for m in months}\n    for r in rows:\n        m = _day(r[\'month\'])\n        if m in data:\n            key = \'in\' if r[\'direction\'] == \'IN\' else \'out\'\n            data[m][key] = float(r[\'amount\'] or 0)\n            data[m][key + \'_docs\'] = r[\'docs\']\n    top = max([max(v[\'in\'], v[\'out\']) for v in data.values()] + [0]) or 1\n    out = []\n    for m in months:\n        v = data[m]\n        out.append({\'label\': f\'{MONTHS_RU[m.month - 1]} {m.year}\', **v,\n                    \'net\': v[\'in\'] - v[\'out\'],\n                    \'in_w\': round(100 * v[\'in\'] / top), \'out_w\': round(100 * v[\'out\'] / top)})\n    return out\n\n\ndef build(data, contragentid, pdate):\n    """The whole portfolio as one dict for the template and the Excel file."""\n    accounts = data[\'accounts\']\n    for a in accounts:\n        a.update(classify(a[\'bal_acc\']))\n        a[\'saldo\'] = float(a[\'saldo\'] or 0)\n        a[\'amount\'] = abs(a[\'saldo\'])\n    by_id = {a[\'account_id\']: a for a in accounts}\n    of = lambda section: [a for a in accounts if a[\'section\'] == section]\n\n    # ── loans ──\n    loans = of(\'loan\')\n    loan_rows = _loans_table(loans)\n    gross = sum(r[\'gross\'] for r in loan_rows)\n    overdue = sum(r[\'overdue\'] for r in loan_rows)\n    court = sum(r[\'court\'] for r in loan_rows)\n    restructured = sum(r[\'restructured\'] for r in loan_rows)\n    reserve = sum(r[\'reserve\'] for r in loan_rows)\n    interest = of(\'interest\')\n    interest_due = sum(a[\'amount\'] for a in interest if a[\'status\'] != \'reserve\')\n    interest_overdue = sum(a[\'amount\'] for a in interest if a[\'status\'] == \'overdue\')\n\n    # ── deposits and off-balance ──\n    deposit_rows, deposits = _sum_by_label(of(\'deposit\'))\n    off = of(\'offbalance\')\n    off_rows, _ = _sum_by_label(off)\n    off_sum = lambda kind: sum(a[\'amount\'] for a in off if a[\'kind\'] == kind)\n    collateral = off_sum(\'collateral\')\n\n    # ── deals and credit lines ──\n    months = _month_starts(pdate, TURNOVER_MONTHS)\n    overdue_months, overdue_now = _overdue(data.get(\'overdue\', []), pdate, months)\n    deals = _deals(data[\'deals\'], data[\'links\'], by_id, pdate, overdue_now)\n    rnk = _rnk(deals)\n    in_deals = set().union(*(d[\'account_ids\'] for d in deals)) if deals else set()\n    loose = [a for a in loans if a[\'status\'] != \'reserve\' and a[\'account_id\'] not in in_deals]\n\n    # ── turnover ──\n    turnover = _turnover(data[\'turnover\'], pdate)\n    for row, worst in zip(turnover, overdue_months):     # same 6 months, same order\n        row[\'od_days\'], row[\'pr_days\'] = worst[1], worst[2]\n    max_overdue_days = max([max(w.values()) for w in overdue_months] + [0])\n    avg_in = sum(t[\'in\'] for t in turnover) / TURNOVER_MONTHS\n    avg_out = sum(t[\'out\'] for t in turnover) / TURNOVER_MONTHS\n\n    kpis = [\n        {\'label\': \'Кредиты (брутто)\', \'value\': gross, \'note\': f\'{len(deals)} сделок\'},\n        {\'label\': \'Просрочка + суд\', \'value\': overdue + court,\n         \'note\': _pct_txt(overdue + court, gross) + \' портфеля\',\n         \'bad\': bool(overdue + court)},\n        {\'label\': \'Резервы\', \'value\': reserve, \'note\': _pct_txt(reserve, gross) + \' портфеля\'},\n        {\'label\': \'Депозиты и счета\', \'value\': deposits, \'note\': \'все пассивы клиента\'},\n        {\'label\': \'Чистая позиция\', \'value\': deposits - gross,\n         \'note\': \'депозиты − кредиты\', \'bad\': deposits - gross &lt; 0},\n        {\'label\': \'Обеспечение\', \'value\': collateral,\n         \'note\': \'покрытие \' + _pct_txt(collateral, gross) if gross else \'кредитов нет\'},\n        {\'label\': \'Поступления в мес.\', \'value\': avg_in, \'note\': f\'среднее за {TURNOVER_MONTHS} мес.\'},\n    ]\n\n    return {\n        \'contragentid\': contragentid, \'pdate\': pdate, \'name\': data[\'name\'] or \'—\',\n        \'client_type\': client_type(a[\'bal_acc\'] for a in accounts),\n        \'kpis\': kpis,\n        \'loans\': {\n            \'rows\': loan_rows, \'gross\': gross, \'net\': gross - reserve, \'reserve\': reserve,\n            \'current\': sum(r[\'current\'] for r in loan_rows), \'restructured\': restructured,\n            \'overdue\': overdue, \'court\': court,\n            \'problem_pct\': _pct(overdue + court, gross),\n            \'interest_due\': interest_due, \'interest_overdue\': interest_overdue,\n            \'written_off\': off_sum(\'written_off\'),\n        },\n        \'deals\': deals, \'rnk\': rnk, \'loose\': loose,\n        \'deposits\': {\'rows\': deposit_rows, \'total\': deposits},\n        \'offbalance\': {\'rows\': off_rows, \'collateral\': collateral,\n                       \'coverage_pct\': _pct(collateral, gross), \'unused\': off_sum(\'unused\'),\n                       \'guarantees\': off_sum(\'guarantee\')},\n        \'turnover\': {\'months\': turnover, \'avg_in\': avg_in, \'avg_out\': avg_out,\n                     \'total_in\': avg_in * TURNOVER_MONTHS,\n                     # "the debt equals N months of income"\n                     \'max_overdue_days\': max_overdue_days,\n                     \'debt_months\': round(gross / avg_in, 1) if avg_in and gross else None},\n        \'accounts\': accounts,\n    }\n</code></pre>\n'})

TUTORIALS.append({'title': 'CP-7. excel.py', 'category': 'programming', 'order': 7, 'summary': 'The same portfolio as an .xlsx file, one sheet per section (openpyxl).', 'content': '<p>Step 7 of 9. Save as <code>cprofile/excel.py</code>.</p>\n<h3>excel.py</h3>\n<pre><code class="language-python">"""The portfolio as an .xlsx file: one sheet per section of the page, same numbers."""\nfrom openpyxl import Workbook\nfrom openpyxl.styles import Font, PatternFill\n\nHEAD_FILL = PatternFill("solid", fgColor="F2C230")\nMONEY = "#,##0"\n\n\ndef _sheet(wb, title, headers, rows, money_cols=()):\n    ws = wb.create_sheet(title)\n    ws.append(headers)\n    for cell in ws[1]:\n        cell.font = Font(bold=True)\n        cell.fill = HEAD_FILL\n    for r in rows:\n        ws.append(list(r))\n    for col in money_cols:                      # 1-based column numbers\n        for row in ws.iter_rows(min_row=2, min_col=col, max_col=col):\n            row[0].number_format = MONEY\n    for i, h in enumerate(headers, start=1):\n        ws.column_dimensions[ws.cell(1, i).column_letter].width = max(14, len(h) + 4)\n    ws.freeze_panes = "A2"\n    return ws\n\n\ndef write(p, stream):\n    wb = Workbook()\n    wb.remove(wb.active)\n\n    _sheet(wb, "Сводка", ["Показатель", "Значение", "Комментарий"],\n           [("Контрагент", p["name"], p["contragentid"]),\n            ("Дата", p["pdate"].strftime("%d.%m.%Y"), p["client_type"])]\n           + [(k["label"], round(k["value"]), k["note"]) for k in p["kpis"]], money_cols=[2])\n\n    L = p["loans"]\n    _sheet(wb, "Кредиты", ["Продукт", "Срочные", "Реструкт.", "Просрочка", "Суд", "Брутто",\n                           "Резерв", "Нетто"],\n           [(r["label"], r["current"], r["restructured"], r["overdue"], r["court"], r["gross"],\n             r["reserve"], r["net"]) for r in L["rows"]]\n           + [("ИТОГО", L["current"], L["restructured"], L["overdue"], L["court"], L["gross"],\n               L["reserve"], L["net"])], money_cols=range(2, 9))\n\n    _sheet(wb, "Сделки", ["Сделка", "РНК", "Валюта", "Выдано (экв.)", "Остаток", "Просрочка",\n                          "Дн. просрочки", "Проценты", "Неисп. линия", "Дата закрытия",\n                          "Дней осталось", "Счета"],\n           [(d["dealid"], d["rnk_dealid"], d["currencyid"], d["given"], d["balance"],\n             d["overdue"], d["overdue_days"], d["interest"], d["unused"], d["close_date"],\n             d["days_left"], ", ".join(d["loan_accounts"])) for d in p["deals"]],\n           money_cols=[4, 5, 6, 8, 9])\n\n    _sheet(wb, "РНК", ["РНК", "Сделок", "Выдано (экв.)", "Остаток", "Просрочка", "Неисп. линия",\n                       "Последнее закрытие", "Дней осталось"],\n           [(r["rnk_dealid"], r["deals"], r["given"], r["balance"], r["overdue"], r["unused"],\n             r["last_close"], r["days_left"]) for r in p["rnk"]], money_cols=[3, 4, 5, 6])\n\n    _sheet(wb, "Депозиты", ["Вид", "Сумма", "Счетов", "Доля, %"],\n           [(r["label"], r["amount"], r["count"], r["share"]) for r in p["deposits"]["rows"]],\n           money_cols=[2])\n\n    _sheet(wb, "Внебаланс", ["Вид", "Сумма", "Счетов"],\n           [(r["label"], r["amount"], r["count"]) for r in p["offbalance"]["rows"]],\n           money_cols=[2])\n\n    _sheet(wb, "Обороты", ["Месяц", "Поступления", "Документов", "Списания", "Документов",\n                           "Сальдо", "Просрочка ОД, дн.", "Просрочка %, дн."],\n           [(m["label"], m["in"], m["in_docs"], m["out"], m["out_docs"], m["net"],\n             m["od_days"], m["pr_days"]) for m in p["turnover"]["months"]],\n           money_cols=[2, 4, 6])\n\n    _sheet(wb, "Счета", ["Счёт", "Бал. счёт", "Валюта", "TOBO", "Раздел", "Что это", "Сальдо (как в базе)"],\n           [(a["accountno"], a["bal_acc"], a["currency_code"], a["toboid"], a["section"],\n             a["label"], a["saldo"]) for a in p["accounts"]], money_cols=[7])\n\n    wb.save(stream)\n</code></pre>\n'})

TUTORIALS.append({'title': 'CP-8. views.py', 'category': 'programming', 'order': 8, 'summary': 'The page (GET form → portfolio) and the Excel download.', 'content': '<p>Step 8 of 9. Save as <code>cprofile/views.py</code>.</p>\n<h3>views.py</h3>\n<pre><code class="language-python">"""\nTwo views: the page (form + portfolio) and the same portfolio as an Excel file.\n\nThe form uses GET, so a portfolio has its own link: /cprofile/?contragentid=123&amp;pdate=2026-10-01\n— send it to a colleague and they see the same thing.\n"""\nimport re\nfrom datetime import date\n\nimport oracledb\nfrom django.http import HttpResponse\nfrom django.shortcuts import render\n\nfrom . import excel as excel_file\nfrom . import logic, queries\n\n\ndef _params(request):\n    """(contragentid, pdate, error). Error is a Russian message or None."""\n    # digits only: with USE_THOUSAND_SEPARATOR an id can arrive as "12 345 678"\n    cid = re.sub(r"\\D", "", request.GET.get("contragentid", ""))\n    pd = request.GET.get("pdate", "").strip()\n    if not cid.isdigit():\n        return None, None, "Введите ID контрагента (только цифры)."\n    try:\n        pdate = date.fromisoformat(pd)\n    except ValueError:\n        return None, None, "Выберите дату."\n    return int(cid), pdate, None\n\n\ndef _portfolio(request):\n    """(portfolio, error): load from Oracle and build."""\n    cid, pdate, error = _params(request)\n    if error:\n        return None, error\n    try:\n        data = queries.load_client(cid, pdate)\n    except oracledb.Error as e:\n        return None, f"Ошибка базы данных: {e}"\n    if not data["accounts"] and not data["deals"]:\n        return None, f"На {pdate:%d.%m.%Y} у контрагента {cid} нет счетов с остатком и живых сделок."\n    return logic.build(data, cid, pdate), None\n\n\ndef page(request):\n    ctx = {"form": {"contragentid": request.GET.get("contragentid", ""),\n                    "pdate": request.GET.get("pdate", "")}}\n    if "contragentid" in request.GET:\n        ctx["p"], ctx["error"] = _portfolio(request)\n    return render(request, "cprofile/page.html", ctx)\n\n\ndef excel(request):\n    p, error = _portfolio(request)\n    if error:\n        return HttpResponse(error, status=400, content_type="text/plain; charset=utf-8")\n    response = HttpResponse(\n        content_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")\n    response["Content-Disposition"] = (\n        f\'attachment; filename="portfolio_{p["contragentid"]}_{p["pdate"]:%Y%m%d}.xlsx"\')\n    excel_file.write(p, response)\n    return response\n</code></pre>\n'})

TUTORIALS.append({'title': 'CP-9. templates/cprofile/page.html', 'category': 'programming', 'order': 9, 'summary': 'The page: form, header, KPIs, loans, deals, RNK, deposits, off-balance, turnover, all accounts. Bootstrap, no JS except the print button.', 'content': '<p>Step 9 of 9. Save as <code>cprofile/templates/cprofile/page.html</code>.</p>\n<h3>templates/cprofile/page.html</h3>\n<pre><code class="language-html">{% extends "base.html" %}\n{% load l10n %}\n{% comment %}\n  Client portfolio: the form, then the portfolio of one client on one date.\n  Bootstrap 5 from base.html + a small stylesheet scoped under .cpf.\n  No JavaScript except the one-line «Печать» button.\n  Money: floatformat:"0g" = whole so\'m with thousands grouped.\n  Ids: |unlocalize, or USE_THOUSAND_SEPARATOR prints 12345678 as "12 345 678".\n{% endcomment %}\n\n{% block extra_css %}\n&lt;style&gt;\n  .cpf{--ink:#0B0B0C;--soft:#2A2A2E;--gold:#F2C230;--gd:#C9971A;--gtext:#8C6A12;\n       --rule:#E4E1D8;--muted:#8A867C;--bad:#B3341F;--warn:#D9822B;\n       font-family:Cambria,Georgia,serif;color:var(--ink)}\n  .cpf .hero{background:var(--ink);color:#fff;border-radius:10px;padding:24px 28px;margin-bottom:20px}\n  .cpf .eyebrow{font-size:10.5px;letter-spacing:.22em;text-transform:uppercase;color:var(--gold)}\n  .cpf .hero h1{font-weight:400;font-size:28px;margin:6px 0 4px}\n  .cpf .hero .sub{color:#B9B5AB;font-size:13.5px}\n  .cpf .card{border:1px solid var(--rule);border-radius:10px;margin-bottom:20px;break-inside:avoid}\n  .cpf .card-header{background:#FAF8F2;border-bottom:1px solid var(--rule);font-size:11px;\n       letter-spacing:.14em;text-transform:uppercase;color:var(--gtext);padding:10px 16px}\n  .cpf .card-header .hint{letter-spacing:0;text-transform:none;color:var(--muted);float:right}\n  .cpf .form-label{font-size:10.5px;letter-spacing:.12em;text-transform:uppercase;color:var(--muted)}\n  .cpf .btn-go{background:var(--gold);border:none;color:var(--ink);font-weight:600;padding:8px 26px}\n  .cpf .btn-go:hover{background:var(--gd)}\n  .cpf .kpi{border:1px solid var(--rule);border-radius:10px;padding:12px 14px;height:100%;background:#fff}\n  .cpf .kpi .l{font-size:10px;letter-spacing:.12em;text-transform:uppercase;color:var(--muted)}\n  .cpf .kpi .v{font-size:20px;line-height:1.25;margin-top:4px;white-space:nowrap}\n  .cpf .kpi .n{font-size:12px;color:var(--muted)}\n  .cpf .kpi.bad{border-color:var(--bad)} .cpf .kpi.bad .v{color:var(--bad)}\n  .cpf table{font-size:13px;margin:0}\n  .cpf th{font-size:10.5px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);\n          font-weight:600;white-space:nowrap}\n  .cpf td.m,.cpf th.m{text-align:right;white-space:nowrap;font-variant-numeric:tabular-nums}\n  .cpf tr.total td{font-weight:700;border-top:2px solid var(--soft)}\n  .cpf .red{color:var(--bad)} .cpf .zero{color:#C8C4BA}\n  .cpf .acc{font-family:Consolas,monospace;font-size:11.5px;color:var(--soft)}\n  .cpf .bar{height:9px;border-radius:2px;display:block;min-width:2px}\n  .cpf .bar.in{background:var(--gold)} .cpf .bar.out{background:var(--soft)}\n  .cpf .note{font-size:12.5px;color:var(--muted);padding:10px 16px;border-top:1px solid var(--rule)}\n  .cpf details summary{cursor:pointer;color:var(--gtext);font-size:13px;padding:10px 16px}\n  @media print{\n    .sb-topnav,#layoutSidenav_nav,.cpf .no-print{display:none!important}\n    #layoutSidenav_content{padding-left:0!important;margin-left:0!important}\n    .cpf .hero{-webkit-print-color-adjust:exact;print-color-adjust:exact}\n    .cpf details{display:block} .cpf details&gt;*{display:block}\n  }\n&lt;/style&gt;\n{% endblock extra_css %}\n\n{% block content %}\n&lt;div class="cpf container-fluid px-4 py-4"&gt;\n\n  {# ── the form ── #}\n  &lt;div class="card no-print"&gt;\n    &lt;div class="card-header"&gt;Портфель клиента&lt;/div&gt;\n    &lt;div class="card-body"&gt;\n      &lt;form method="get" class="row g-3 align-items-end"&gt;\n        &lt;div class="col-sm-4 col-md-3"&gt;\n          &lt;label class="form-label" for="cid"&gt;ID контрагента&lt;/label&gt;\n          &lt;input class="form-control" id="cid" name="contragentid" inputmode="numeric"\n                 value="{{ form.contragentid }}" required&gt;\n        &lt;/div&gt;\n        &lt;div class="col-sm-4 col-md-3"&gt;\n          &lt;label class="form-label" for="pd"&gt;Дата (arcdate)&lt;/label&gt;\n          &lt;input class="form-control" id="pd" type="date" name="pdate" value="{{ form.pdate }}" required&gt;\n        &lt;/div&gt;\n        &lt;div class="col-sm-4 col-md-3"&gt;\n          &lt;button class="btn btn-go" type="submit"&gt;Показать&lt;/button&gt;\n        &lt;/div&gt;\n      &lt;/form&gt;\n    &lt;/div&gt;\n  &lt;/div&gt;\n\n  {% if error %}&lt;div class="alert alert-warning"&gt;{{ error }}&lt;/div&gt;{% endif %}\n\n  {% if p %}\n  {# ── header ── #}\n  &lt;div class="hero d-flex flex-wrap justify-content-between align-items-end gap-3"&gt;\n    &lt;div&gt;\n      &lt;div class="eyebrow"&gt;Портфель клиента на {{ p.pdate|date:"d.m.Y" }}&lt;/div&gt;\n      &lt;h1&gt;{{ p.name }}&lt;/h1&gt;\n      &lt;div class="sub"&gt;ID {{ p.contragentid|unlocalize }} · {{ p.client_type }} · {{ p.accounts|length }} счетов с остатком&lt;/div&gt;\n    &lt;/div&gt;\n    &lt;div class="no-print d-flex gap-2"&gt;\n      &lt;a class="btn btn-go btn-sm" href="{% url \'client-portfolio-excel\' %}?contragentid={{ p.contragentid|unlocalize }}&amp;pdate={{ p.pdate|date:\'Y-m-d\' }}"&gt;\n        &lt;i class="fas fa-file-excel me-1"&gt;&lt;/i&gt;Excel&lt;/a&gt;\n      &lt;button class="btn btn-outline-light btn-sm" type="button" onclick="window.print()"&gt;\n        &lt;i class="fas fa-print me-1"&gt;&lt;/i&gt;Печать / PDF&lt;/button&gt;\n    &lt;/div&gt;\n  &lt;/div&gt;\n\n  {# ── KPIs ── #}\n  &lt;div class="row g-3 mb-4"&gt;\n    {% for k in p.kpis %}\n    &lt;div class="col-6 col-md-4 col-xl"&gt;\n      &lt;div class="kpi{% if k.bad %} bad{% endif %}"&gt;\n        &lt;div class="l"&gt;{{ k.label }}&lt;/div&gt;\n        &lt;div class="v"&gt;{{ k.value|floatformat:"0g" }}&lt;/div&gt;\n        &lt;div class="n"&gt;{{ k.note }}&lt;/div&gt;\n      &lt;/div&gt;\n    &lt;/div&gt;\n    {% endfor %}\n  &lt;/div&gt;\n\n  {# ── loans by product ── #}\n  &lt;div class="card"&gt;\n    &lt;div class="card-header"&gt;Кредиты по продуктам &lt;span class="hint"&gt;сум, эквивалент&lt;/span&gt;&lt;/div&gt;\n    {% if p.loans.rows %}\n    &lt;div class="table-responsive"&gt;\n      &lt;table class="table table-sm table-hover"&gt;\n        &lt;thead&gt;&lt;tr&gt;&lt;th&gt;Продукт&lt;/th&gt;&lt;th class="m"&gt;Срочные&lt;/th&gt;&lt;th class="m"&gt;Реструкт.&lt;/th&gt;\n          &lt;th class="m"&gt;Просрочка&lt;/th&gt;&lt;th class="m"&gt;Суд&lt;/th&gt;&lt;th class="m"&gt;Брутто&lt;/th&gt;\n          &lt;th class="m"&gt;Резерв&lt;/th&gt;&lt;th class="m"&gt;Нетто&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;\n        &lt;tbody&gt;\n        {% for r in p.loans.rows %}\n          &lt;tr&gt;&lt;td&gt;{{ r.label }}&lt;/td&gt;\n            &lt;td class="m"&gt;{{ r.current|floatformat:"0g" }}&lt;/td&gt;\n            &lt;td class="m{% if not r.restructured %} zero{% endif %}"&gt;{{ r.restructured|floatformat:"0g" }}&lt;/td&gt;\n            &lt;td class="m{% if r.overdue %} red{% else %} zero{% endif %}"&gt;{{ r.overdue|floatformat:"0g" }}&lt;/td&gt;\n            &lt;td class="m{% if r.court %} red{% else %} zero{% endif %}"&gt;{{ r.court|floatformat:"0g" }}&lt;/td&gt;\n            &lt;td class="m"&gt;{{ r.gross|floatformat:"0g" }}&lt;/td&gt;\n            &lt;td class="m"&gt;{{ r.reserve|floatformat:"0g" }}&lt;/td&gt;\n            &lt;td class="m"&gt;{{ r.net|floatformat:"0g" }}&lt;/td&gt;&lt;/tr&gt;\n        {% endfor %}\n          &lt;tr class="total"&gt;&lt;td&gt;Итого&lt;/td&gt;\n            &lt;td class="m"&gt;{{ p.loans.current|floatformat:"0g" }}&lt;/td&gt;\n            &lt;td class="m"&gt;{{ p.loans.restructured|floatformat:"0g" }}&lt;/td&gt;\n            &lt;td class="m"&gt;{{ p.loans.overdue|floatformat:"0g" }}&lt;/td&gt;\n            &lt;td class="m"&gt;{{ p.loans.court|floatformat:"0g" }}&lt;/td&gt;\n            &lt;td class="m"&gt;{{ p.loans.gross|floatformat:"0g" }}&lt;/td&gt;\n            &lt;td class="m"&gt;{{ p.loans.reserve|floatformat:"0g" }}&lt;/td&gt;\n            &lt;td class="m"&gt;{{ p.loans.net|floatformat:"0g" }}&lt;/td&gt;&lt;/tr&gt;\n        &lt;/tbody&gt;\n      &lt;/table&gt;\n    &lt;/div&gt;\n    &lt;div class="note"&gt;\n      Начисленные проценты: &lt;strong&gt;{{ p.loans.interest_due|floatformat:"0g" }}&lt;/strong&gt;,\n      из них просроченные: &lt;strong{% if p.loans.interest_overdue %} class="red"{% endif %}&gt;{{ p.loans.interest_overdue|floatformat:"0g" }}&lt;/strong&gt;.\n      {% if p.loans.written_off %}Списано за баланс (95413): &lt;strong class="red"&gt;{{ p.loans.written_off|floatformat:"0g" }}&lt;/strong&gt;.{% endif %}\n      {% if p.loans.problem_pct %}Проблемные (просрочка + суд): &lt;strong class="red"&gt;{{ p.loans.problem_pct }}%&lt;/strong&gt; портфеля.{% endif %}\n    &lt;/div&gt;\n    {% else %}\n    &lt;div class="card-body text-muted"&gt;Кредитов на эту дату нет.&lt;/div&gt;\n    {% endif %}\n  &lt;/div&gt;\n\n  {# ── deals ── #}\n  {% if p.deals %}\n  &lt;div class="card"&gt;\n    &lt;div class="card-header"&gt;Активные сделки &lt;span class="hint"&gt;с остатком на дату&lt;/span&gt;&lt;/div&gt;\n    &lt;div class="table-responsive"&gt;\n      &lt;table class="table table-sm table-hover"&gt;\n        &lt;thead&gt;&lt;tr&gt;&lt;th&gt;Сделка&lt;/th&gt;&lt;th&gt;РНК&lt;/th&gt;&lt;th&gt;Вал.&lt;/th&gt;&lt;th class="m"&gt;Выдано (экв.)&lt;/th&gt;\n          &lt;th class="m"&gt;Остаток&lt;/th&gt;&lt;th class="m"&gt;Просрочка&lt;/th&gt;&lt;th class="m"&gt;Дн. просрочки&lt;/th&gt;\n          &lt;th class="m"&gt;Проценты&lt;/th&gt;&lt;th&gt;Закрытие&lt;/th&gt;&lt;th class="m"&gt;Дней&lt;/th&gt;&lt;th&gt;&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;\n        &lt;tbody&gt;\n        {% for d in p.deals %}\n          &lt;tr&gt;&lt;td&gt;{{ d.dealid|unlocalize }}&lt;div class="acc"&gt;{% for n in d.loan_accounts %}{{ n }}&lt;br&gt;{% endfor %}&lt;/div&gt;&lt;/td&gt;\n            &lt;td&gt;{% if d.rnk_dealid %}{{ d.rnk_dealid|unlocalize }}{% else %}—{% endif %}&lt;/td&gt;\n            &lt;td&gt;{{ d.currencyid|unlocalize }}&lt;/td&gt;\n            &lt;td class="m"&gt;{{ d.given|floatformat:"0g" }}&lt;/td&gt;\n            &lt;td class="m"&gt;{{ d.balance|floatformat:"0g" }}&lt;/td&gt;\n            &lt;td class="m{% if d.overdue %} red{% else %} zero{% endif %}"&gt;{{ d.overdue|floatformat:"0g" }}&lt;/td&gt;\n            &lt;td class="m{% if d.overdue_days %} red{% else %} zero{% endif %}"&gt;{{ d.overdue_days|default:"—" }}&lt;/td&gt;\n            &lt;td class="m"&gt;{{ d.interest|floatformat:"0g" }}&lt;/td&gt;\n            &lt;td&gt;{{ d.close_date|date:"d.m.Y"|default:"—" }}&lt;/td&gt;\n            &lt;td class="m"&gt;{{ d.days_left|default_if_none:"—" }}&lt;/td&gt;\n            &lt;td&gt;{% if d.flag %}&lt;span class="badge bg-{{ d.flag.0 }}"&gt;{{ d.flag.1 }}&lt;/span&gt;{% endif %}&lt;/td&gt;&lt;/tr&gt;\n        {% endfor %}\n        &lt;/tbody&gt;\n      &lt;/table&gt;\n    &lt;/div&gt;\n    {% if p.loose %}\n    &lt;div class="note"&gt;Счета кредитов без живой сделки ({{ p.loose|length }}):\n      {% for a in p.loose %}&lt;span class="acc"&gt;{{ a.accountno }}&lt;/span&gt; — {{ a.amount|floatformat:"0g" }}{% if not forloop.last %}; {% endif %}{% endfor %}.\n      Их нет в portfel_table на эту дату — стоит проверить.&lt;/div&gt;\n    {% endif %}\n  &lt;/div&gt;\n  {% endif %}\n\n  {# ── credit lines ── #}\n  {% if p.rnk %}\n  &lt;div class="card"&gt;\n    &lt;div class="card-header"&gt;Кредитные линии (РНК) &lt;span class="hint"&gt;сумма сделок внутри линии, не лимит&lt;/span&gt;&lt;/div&gt;\n    &lt;div class="table-responsive"&gt;\n      &lt;table class="table table-sm"&gt;\n        &lt;thead&gt;&lt;tr&gt;&lt;th&gt;РНК&lt;/th&gt;&lt;th class="m"&gt;Сделок&lt;/th&gt;&lt;th class="m"&gt;Выдано (экв.)&lt;/th&gt;\n          &lt;th class="m"&gt;Остаток&lt;/th&gt;&lt;th class="m"&gt;Просрочка&lt;/th&gt;&lt;th class="m"&gt;Неисп. линия (91809)&lt;/th&gt;\n          &lt;th&gt;Последнее закрытие&lt;/th&gt;&lt;th class="m"&gt;Дней&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;\n        &lt;tbody&gt;\n        {% for r in p.rnk %}\n          &lt;tr&gt;&lt;td&gt;{{ r.rnk_dealid|unlocalize }}&lt;/td&gt;&lt;td class="m"&gt;{{ r.deals }}&lt;/td&gt;\n            &lt;td class="m"&gt;{{ r.given|floatformat:"0g" }}&lt;/td&gt;\n            &lt;td class="m"&gt;{{ r.balance|floatformat:"0g" }}&lt;/td&gt;\n            &lt;td class="m{% if r.overdue %} red{% else %} zero{% endif %}"&gt;{{ r.overdue|floatformat:"0g" }}&lt;/td&gt;\n            &lt;td class="m{% if not r.unused %} zero{% endif %}"&gt;{{ r.unused|floatformat:"0g" }}&lt;/td&gt;\n            &lt;td&gt;{{ r.last_close|date:"d.m.Y"|default:"—" }}&lt;/td&gt;\n            &lt;td class="m"&gt;{{ r.days_left|default_if_none:"—" }}&lt;/td&gt;&lt;/tr&gt;\n        {% endfor %}\n        &lt;/tbody&gt;\n      &lt;/table&gt;\n    &lt;/div&gt;\n  &lt;/div&gt;\n  {% endif %}\n\n  &lt;div class="row g-3"&gt;\n    {# ── deposits ── #}\n    &lt;div class="col-lg-6"&gt;\n      &lt;div class="card h-100"&gt;\n        &lt;div class="card-header"&gt;Депозиты и счета клиента&lt;/div&gt;\n        {% if p.deposits.rows %}\n        &lt;table class="table table-sm"&gt;\n          &lt;thead&gt;&lt;tr&gt;&lt;th&gt;Вид&lt;/th&gt;&lt;th class="m"&gt;Счетов&lt;/th&gt;&lt;th class="m"&gt;Сумма&lt;/th&gt;&lt;th class="m"&gt;Доля&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;\n          &lt;tbody&gt;\n          {% for r in p.deposits.rows %}\n            &lt;tr&gt;&lt;td&gt;{{ r.label }}&lt;/td&gt;&lt;td class="m"&gt;{{ r.count }}&lt;/td&gt;\n              &lt;td class="m"&gt;{{ r.amount|floatformat:"0g" }}&lt;/td&gt;&lt;td class="m"&gt;{{ r.share }}%&lt;/td&gt;&lt;/tr&gt;\n          {% endfor %}\n            &lt;tr class="total"&gt;&lt;td&gt;Итого&lt;/td&gt;&lt;td&gt;&lt;/td&gt;&lt;td class="m"&gt;{{ p.deposits.total|floatformat:"0g" }}&lt;/td&gt;&lt;td&gt;&lt;/td&gt;&lt;/tr&gt;\n          &lt;/tbody&gt;\n        &lt;/table&gt;\n        {% else %}&lt;div class="card-body text-muted"&gt;Остатков на счетах нет.&lt;/div&gt;{% endif %}\n      &lt;/div&gt;\n    &lt;/div&gt;\n    {# ── off-balance ── #}\n    &lt;div class="col-lg-6"&gt;\n      &lt;div class="card h-100"&gt;\n        &lt;div class="card-header"&gt;Внебалансовые счета&lt;/div&gt;\n        {% if p.offbalance.rows %}\n        &lt;table class="table table-sm"&gt;\n          &lt;thead&gt;&lt;tr&gt;&lt;th&gt;Вид&lt;/th&gt;&lt;th class="m"&gt;Счетов&lt;/th&gt;&lt;th class="m"&gt;Сумма&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;\n          &lt;tbody&gt;\n          {% for r in p.offbalance.rows %}\n            &lt;tr&gt;&lt;td&gt;{{ r.label }}&lt;/td&gt;&lt;td class="m"&gt;{{ r.count }}&lt;/td&gt;\n              &lt;td class="m"&gt;{{ r.amount|floatformat:"0g" }}&lt;/td&gt;&lt;/tr&gt;\n          {% endfor %}\n          &lt;/tbody&gt;\n        &lt;/table&gt;\n        {% if p.offbalance.coverage_pct is not None %}\n        &lt;div class="note"&gt;Обеспечение покрывает &lt;strong&gt;{{ p.offbalance.coverage_pct }}%&lt;/strong&gt; кредитного портфеля\n          (залоги 945xx ÷ кредиты брутто).&lt;/div&gt;\n        {% endif %}\n        {% else %}&lt;div class="card-body text-muted"&gt;Внебалансовых остатков нет.&lt;/div&gt;{% endif %}\n      &lt;/div&gt;\n    &lt;/div&gt;\n  &lt;/div&gt;\n\n  {# ── turnover ── #}\n  &lt;div class="card mt-3"&gt;\n    &lt;div class="card-header"&gt;Обороты и просрочка за {{ p.turnover.months|length }} мес.\n      &lt;span class="hint"&gt;обороты без переводов между своими счетами&lt;/span&gt;&lt;/div&gt;\n    &lt;div class="table-responsive"&gt;\n      &lt;table class="table table-sm"&gt;\n        &lt;thead&gt;&lt;tr&gt;&lt;th&gt;Месяц&lt;/th&gt;&lt;th class="m"&gt;Поступления&lt;/th&gt;&lt;th class="m"&gt;Док.&lt;/th&gt;\n          &lt;th class="m"&gt;Списания&lt;/th&gt;&lt;th class="m"&gt;Док.&lt;/th&gt;&lt;th class="m"&gt;Сальдо&lt;/th&gt;\n          &lt;th style="width:24%"&gt;&lt;/th&gt;\n          &lt;th class="m" title="максимум за месяц"&gt;Просрочка ОД, дн.&lt;/th&gt;\n          &lt;th class="m" title="максимум за месяц"&gt;Просрочка %, дн.&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;\n        &lt;tbody&gt;\n        {% for m in p.turnover.months %}\n          &lt;tr&gt;&lt;td&gt;{{ m.label }}&lt;/td&gt;\n            &lt;td class="m"&gt;{{ m.in|floatformat:"0g" }}&lt;/td&gt;&lt;td class="m"&gt;{{ m.in_docs }}&lt;/td&gt;\n            &lt;td class="m"&gt;{{ m.out|floatformat:"0g" }}&lt;/td&gt;&lt;td class="m"&gt;{{ m.out_docs }}&lt;/td&gt;\n            &lt;td class="m{% if m.net &lt; 0 %} red{% endif %}"&gt;{{ m.net|floatformat:"0g" }}&lt;/td&gt;\n            &lt;td&gt;&lt;span class="bar in" style="width:{{ m.in_w }}%"&gt;&lt;/span&gt;\n                &lt;span class="bar out mt-1" style="width:{{ m.out_w }}%"&gt;&lt;/span&gt;&lt;/td&gt;\n            &lt;td class="m{% if m.od_days %} red{% else %} zero{% endif %}"&gt;{{ m.od_days|default:"—" }}&lt;/td&gt;\n            &lt;td class="m{% if m.pr_days %} red{% else %} zero{% endif %}"&gt;{{ m.pr_days|default:"—" }}&lt;/td&gt;&lt;/tr&gt;\n        {% endfor %}\n        &lt;/tbody&gt;\n      &lt;/table&gt;\n    &lt;/div&gt;\n    &lt;div class="note"&gt;\n      &lt;span class="bar in d-inline-block" style="width:14px"&gt;&lt;/span&gt; поступления ·\n      &lt;span class="bar out d-inline-block" style="width:14px"&gt;&lt;/span&gt; списания.\n      В среднем поступает &lt;strong&gt;{{ p.turnover.avg_in|floatformat:"0g" }}&lt;/strong&gt; в месяц.\n      {% if p.turnover.max_overdue_days %}Худшая просрочка за период: &lt;strong class="red"&gt;{{ p.turnover.max_overdue_days }}&lt;/strong&gt; дн.\n      {% else %}Просрочек за период не было.{% endif %}\n      {% if p.turnover.debt_months %}Кредиты брутто = &lt;strong&gt;{{ p.turnover.debt_months }}&lt;/strong&gt; мес. поступлений.{% endif %}\n    &lt;/div&gt;\n  &lt;/div&gt;\n\n  {# ── all accounts, for checking ── #}\n  &lt;div class="card"&gt;\n    &lt;details&gt;\n      &lt;summary&gt;Все счета ({{ p.accounts|length }}) — как в базе&lt;/summary&gt;\n      &lt;div class="table-responsive"&gt;\n        &lt;table class="table table-sm"&gt;\n          &lt;thead&gt;&lt;tr&gt;&lt;th&gt;Счёт&lt;/th&gt;&lt;th&gt;Вал.&lt;/th&gt;&lt;th&gt;TOBO&lt;/th&gt;&lt;th&gt;Что это&lt;/th&gt;&lt;th class="m"&gt;Сальдо в базе&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;\n          &lt;tbody&gt;\n          {% for a in p.accounts %}\n            &lt;tr&gt;&lt;td class="acc"&gt;{{ a.accountno }}&lt;/td&gt;&lt;td&gt;{{ a.currency_code }}&lt;/td&gt;&lt;td&gt;{{ a.toboid|unlocalize }}&lt;/td&gt;\n              &lt;td&gt;{{ a.label }}&lt;/td&gt;&lt;td class="m"&gt;{{ a.saldo|floatformat:"0g" }}&lt;/td&gt;&lt;/tr&gt;\n          {% endfor %}\n          &lt;/tbody&gt;\n        &lt;/table&gt;\n      &lt;/div&gt;\n    &lt;/details&gt;\n  &lt;/div&gt;\n\n  &lt;div class="note no-print"&gt;\n    Суммы — эквивалент в сумах на дату. Кредиты в базе отрицательные, здесь показаны по модулю.\n    Счёт определяется по первым 5 цифрам по плану счетов ЦБ.\n    «Выдано» по РНК — сумма выдач по сделкам линии, это не лимит.\n    Просрочка в месяце — максимум дней по всем сделкам клиента (и закрытым тоже): если просрочка\n    в том месяце ещё не была погашена, дни считаются до последнего дня месяца.\n  &lt;/div&gt;\n  {% endif %}\n&lt;/div&gt;\n{% endblock content %}\n</code></pre>\n', 'renamed_from': ['CP-9. templates/client_portfolio/page.html']})
